CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, steam_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), telemetry_consent boolean NOT NULL DEFAULT false, analytics_consent boolean NOT NULL DEFAULT false, retention_days integer NOT NULL DEFAULT 30 CHECK(retention_days BETWEEN 1 AND 90));
CREATE TABLE IF NOT EXISTS app_sessions (token_hash text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS devices (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, token_hash text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS pairing_codes (code_hash text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, device_id text REFERENCES devices(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS live_sessions (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id text NOT NULL REFERENCES devices(id) ON DELETE CASCADE, sequence bigint NOT NULL, state jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS telemetry_events (device_id text NOT NULL REFERENCES devices(id) ON DELETE CASCADE, event_id text NOT NULL, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(device_id,event_id));
CREATE TABLE IF NOT EXISTS openid_states (state_hash text PRIMARY KEY, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS openid_nonces (nonce text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_codes (code_hash text PRIMARY KEY, binding_hash text NOT NULL, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS demo_jobs (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, filename text NOT NULL, object_key text NOT NULL UNIQUE, checksum text NOT NULL, size bigint NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','processing','complete','failed')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, lease_token text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), error text, analysis jsonb, coaching jsonb);
CREATE INDEX IF NOT EXISTS demo_jobs_queue ON demo_jobs(status,lease_until,created_at);
CREATE INDEX IF NOT EXISTS demo_jobs_owner ON demo_jobs(owner_id,created_at);
CREATE TABLE IF NOT EXISTS feedback (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_events (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, properties jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS file_deletions (object_key text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS provider_usage (owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, day date NOT NULL DEFAULT CURRENT_DATE, requests integer NOT NULL DEFAULT 0, PRIMARY KEY(owner_id,day));
